-- Unicelerate: curated international universities — universities, part 01
-- Generated by scripts/curated/build-international-sql.mjs from data/curated/.
-- Figures were checked by hand on each university's own website (URLs stored
-- with each row). Converted amounts use ECB rates of 2026-10-05.
-- Run after migration_011 and migration_025, files in order. Safe to re-run.

on conflict (curated_id) do update set
  name = excluded.name,
  aliases = excluded.aliases,
  country = excluded.country,
  city = excluded.city,
  degree_levels = excluded.degree_levels,
  tuition = excluded.tuition,
  tuition_local = excluded.tuition_local,
  tuition_currency = excluded.tuition_currency,
  tuition_basis = excluded.tuition_basis,
  tuition_year = excluded.tuition_year,
  tuition_source_url = excluded.tuition_source_url,
  living_cost_per_year = excluded.living_cost_per_year,
  living_cost_local = excluded.living_cost_local,
  living_cost_currency = excluded.living_cost_currency,
  living_cost_source_url = excluded.living_cost_source_url,
  fx_rate_date = excluded.fx_rate_date,
  acceptance_rate = excluded.acceptance_rate,
  acceptance_source_url = excluded.acceptance_source_url,
  popular_programs = excluded.popular_programs,
  programs_source_url = excluded.programs_source_url,
  coop_program = excluded.coop_program,
  internship_support_url = excluded.internship_support_url,
  coop_checked_on = excluded.coop_checked_on,
  source = excluded.source,
  source_url = excluded.source_url,
  data_year = excluded.data_year,
  fetched_at = excluded.fetched_at,
  description = excluded.description,
  is_featured = excluded.is_featured,
  qs_ranking = excluded.qs_ranking,
  program_rankings = excluded.program_rankings,
  avg_admitted_gpa = excluded.avg_admitted_gpa,
  sat_25 = excluded.sat_25,
  sat_75 = excluded.sat_75,
  min_ielts = excluded.min_ielts
where universities.created_by is null;
